INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-01-01', 'lesson-phrasal-b1-01', 1, 'phrasal', 'I get up at six every day.', 'Eu me levanto às seis todo dia.', '/aɪ ɡɛt ʌp æt sɪks ˈɛvri deɪ/', '"Get up" = levantar-se (da cama). Não separável. Neutro.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-02', 'lesson-phrasal-b1-01', 2, 'phrasal', 'Do you get along with your sister?', 'Você se dá bem com sua irmã?', '/duː juː ɡɛt əˈlɔːŋ wɪð jʊr ˈsɪstər/', '"Get along (with)" = dar-se bem com. Neutro.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"along","pos":"particle","ipa":"/əˈlɔːŋ/","gloss":"junto (get along = dar-se bem)"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-03', 'lesson-phrasal-b1-01', 3, 'phrasal', 'It took me months to get over the breakup.', 'Levei meses para superar o término.', '/ɪt tʊk miː mʌnθs tuː ɡɛt ˈoʊvər ðə ˈbreɪkʌp/', '"Get over" = superar (doença, término). Não separável.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"months","pos":"noun","ipa":"/mʌnθs/","gloss":"meses"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"breakup","pos":"noun","ipa":"/ˈbreɪkʌp/","gloss":"término (de namoro)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-04', 'lesson-phrasal-b1-01', 4, 'phrasal', 'I''ll get back to you tomorrow.', 'Te dou um retorno amanhã.', '/aɪl ɡɛt bæk tuː juː təˈmɑːroʊ/', '"Get back to" = dar retorno, responder depois. Muito usado no trabalho.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-05', 'lesson-phrasal-b1-01', 5, 'phrasal', 'Get on the bus at the next stop.', 'Suba no ônibus na próxima parada.', '/ɡɛt ɑːn ðə bʌs æt ðə nɛkst stɑːp/', '"Get on/off" = subir/descer de ônibus, trem, avião. Carro é "get in/out".', '[]'::jsonb, '[{"surface":"Get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"stop","pos":"verb","ipa":"/stɑːp/","gloss":"parar"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-06', 'lesson-phrasal-b1-01', 6, 'phrasal', 'We need to get rid of these old boxes.', 'Precisamos nos livrar dessas caixas velhas.', '/wiː niːd tuː ɡɛt rɪd ʌv ðiːz oʊld ˈbɑːksɪz/', '"Get rid of" = livrar-se de. Neutro.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"rid","pos":"adjective","ipa":"/rɪd/","gloss":"livre (get rid of = livrar-se de)"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"these","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"boxes","pos":"noun","ipa":"/ˈbɑːksɪz/","gloss":"caixas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-07', 'lesson-phrasal-b1-01', 7, 'phrasal', 'How did you get into programming?', 'Como você entrou para a programação?', '/haʊ dɪd juː ɡɛt ˈɪntuː ˈproʊɡræmɪŋ/', '"Get into" = começar a se interessar ou a trabalhar com algo.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"programming","pos":"noun","ipa":"/ˈproʊɡræmɪŋ/","gloss":"programação"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-08', 'lesson-phrasal-b1-01', 8, 'phrasal', 'Let''s get together this weekend.', 'Vamos nos encontrar neste fim de semana.', '/lɛts ɡɛt təˈɡɛðər ðɪs ˈwiːkɛnd/', '"Get together" = reunir-se. Informal.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"together","pos":"adverb","ipa":"/təˈɡɛðər/","gloss":"juntos"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-09', 'lesson-phrasal-b1-01', 9, 'phrasal', 'I can''t get through to the bank.', 'Não consigo falar com o banco.', '/aɪ kænt ɡɛt θruː tuː ðə bæŋk/', '"Get through (to)" = conseguir contato por telefone.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"through","pos":"adverb","ipa":"/θruː/","gloss":"através"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bank","pos":"noun","ipa":"/bæŋk/","gloss":"banco"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-01-10', 'lesson-phrasal-b1-01', 10, 'phrasal', 'He always gets away with it.', 'Ele sempre se safa.', '/hiː ˈɔːlweɪz ɡɛts əˈweɪ wɪð ɪt/', '"Get away with" = sair impune. Informal.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"gets","pos":"verb","ipa":"/ɡɛts/","gloss":"fica"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-02-01', 'lesson-phrasal-b1-02', 1, 'phrasal', 'The plane takes off at noon.', 'O avião decola ao meio-dia.', '/ðə pleɪn teɪks ɔːf æt nuːn/', '"Take off" (sem objeto) = decolar.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plane","pos":"noun","ipa":"/pleɪn/","gloss":"avião"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-02', 'lesson-phrasal-b1-02', 2, 'phrasal', 'Take off your shoes, please.', 'Tire os sapatos, por favor.', '/teɪk ɔːf jʊr ʃuːz pliːz/', '"Take off" (com objeto) = tirar roupa. Separável: "take your shoes off".', '[]'::jsonb, '[{"surface":"Take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"shoes","pos":"noun","ipa":"/ʃuːz/","gloss":"sapatos"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-03', 'lesson-phrasal-b1-02', 3, 'phrasal', 'She takes after her mother.', 'Ela puxou à mãe.', '/ʃiː teɪks ˈæftər hɜːr ˈmʌðər/', '"Take after" = parecer com (parente). Não separável.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"mother","pos":"noun","ipa":"/ˈmʌðər/","gloss":"mãe"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-04', 'lesson-phrasal-b1-02', 4, 'phrasal', 'I took up yoga last year.', 'Comecei a fazer ioga no ano passado.', '/aɪ tʊk ʌp ˈjoʊɡə læst jɪr/', '"Take up" = começar um hobby.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"yoga","pos":"noun","ipa":"/ˈjoʊɡə/","gloss":"ioga"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-05', 'lesson-phrasal-b1-02', 5, 'phrasal', 'Who will take over the project?', 'Quem vai assumir o projeto?', '/huː wɪl teɪk ˈoʊvər ðə ˈprɑːdʒɛkt/', '"Take over" = assumir o controle.', '[]'::jsonb, '[{"surface":"Who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"project","pos":"noun","ipa":"/ˈprɑːdʒɛkt/","gloss":"projeto"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-06', 'lesson-phrasal-b1-02', 6, 'phrasal', 'I take back what I said.', 'Retiro o que eu disse.', '/aɪ teɪk bæk wʌt aɪ sɛd/', '"Take back" = retirar (palavras) ou devolver. Separável.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-07', 'lesson-phrasal-b1-02', 7, 'phrasal', 'Let''s take it easy today.', 'Vamos pegar leve hoje.', '/lɛts teɪk ɪt ˈiːzi təˈdeɪ/', '"Take it easy" = pegar leve, relaxar. Informal.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"easy","pos":"adjective","ipa":"/ˈiːzi/","gloss":"fácil, tranquilo"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-08', 'lesson-phrasal-b1-02', 8, 'phrasal', 'Can you take out the trash?', 'Pode levar o lixo para fora?', '/kæn juː teɪk aʊt ðə træʃ/', '"Take out" = levar para fora; também "take someone out" = levar para sair.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trash","pos":"noun","ipa":"/træʃ/","gloss":"lixo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-09', 'lesson-phrasal-b1-02', 9, 'phrasal', 'This sofa takes up too much space.', 'Este sofá ocupa espaço demais.', '/ðɪs ˈsoʊfə teɪks ʌp tuː mʌtʃ speɪs/', '"Take up space" = ocupar espaço.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"sofa","pos":"noun","ipa":"/ˈsoʊfə/","gloss":"sofá"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"space","pos":"noun","ipa":"/speɪs/","gloss":"espaço"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-02-10', 'lesson-phrasal-b1-02', 10, 'phrasal', 'I''ll take care of it.', 'Eu cuido disso.', '/aɪl teɪk kɛr ʌv ɪt/', '"Take care of" = cuidar de, resolver.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"care","pos":"noun","ipa":"/kɛr/","gloss":"cuidado"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-03-01', 'lesson-phrasal-b1-03', 1, 'phrasal', 'Put on your coat, it is cold.', 'Coloque o casaco, está frio.', '/pʊt ɑːn jʊr koʊt ɪt ɪz koʊld/', '"Put on" = vestir, colocar. Separável: "put it on".', '[]'::jsonb, '[{"surface":"Put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"coat","pos":"noun","ipa":"/koʊt/","gloss":"casaco"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-02', 'lesson-phrasal-b1-03', 2, 'phrasal', 'Let''s not put it off any longer.', 'Não vamos adiar mais.', '/lɛts nɑːt pʊt ɪt ɔːf ˈɛni ˈlɔːŋɡər/', '"Put off" = adiar. Separável.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"longer","pos":"adverb","ipa":"/ˈlɔːŋɡər/","gloss":"mais (tempo)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-03', 'lesson-phrasal-b1-03', 3, 'phrasal', 'I can''t put up with this noise.', 'Não aguento esse barulho.', '/aɪ kænt pʊt ʌp wɪð ðɪs nɔɪz/', '"Put up with" = tolerar. Não separável.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"noise","pos":"noun","ipa":"/nɔɪz/","gloss":"barulho"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-04', 'lesson-phrasal-b1-03', 4, 'phrasal', 'Put away your toys.', 'Guarde seus brinquedos.', '/pʊt əˈweɪ jʊr tɔɪz/', '"Put away" = guardar no lugar.', '[]'::jsonb, '[{"surface":"Put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"toys","pos":"noun","ipa":"/tɔɪz/","gloss":"brinquedos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-05', 'lesson-phrasal-b1-03', 5, 'phrasal', 'The firefighters put out the fire.', 'Os bombeiros apagaram o fogo.', '/ðə ˈfaɪərfaɪtərz pʊt aʊt ðə ˈfaɪər/', '"Put out" = apagar (fogo, cigarro).', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"firefighters","pos":"noun","ipa":"/ˈfaɪərfaɪtərz/","gloss":"bombeiros"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"fire","pos":"noun","ipa":"/ˈfaɪər/","gloss":"fogo, incêndio"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-06', 'lesson-phrasal-b1-03', 6, 'phrasal', 'Can you put me through to sales?', 'Pode me transferir para vendas?', '/kæn juː pʊt miː θruː tuː seɪlz/', '"Put through" = transferir ligação.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"through","pos":"adverb","ipa":"/θruː/","gloss":"através"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"sales","pos":"noun","ipa":"/seɪlz/","gloss":"vendas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-07', 'lesson-phrasal-b1-03', 7, 'phrasal', 'She put down her phone and listened.', 'Ela largou o celular e ouviu.', '/ʃiː pʊt daʊn hɜːr foʊn ænd ˈlɪsənd/', '"Put down" = colocar no chão/mesa, largar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"listened","pos":"verb","ipa":"/ˈlɪsənd/","gloss":"ouviu"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-08', 'lesson-phrasal-b1-03', 8, 'phrasal', 'I''ll put together a report.', 'Vou montar um relatório.', '/aɪl pʊt təˈɡɛðər ə rɪˈpɔːrt/', '"Put together" = montar, organizar.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"together","pos":"adverb","ipa":"/təˈɡɛðər/","gloss":"juntos"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-09', 'lesson-phrasal-b1-03', 9, 'phrasal', 'They put up a new building downtown.', 'Construíram um prédio novo no centro.', '/ðeɪ pʊt ʌp ə nuː ˈbɪldɪŋ ˌdaʊnˈtaʊn/', '"Put up" = construir, erguer; também hospedar alguém.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"building","pos":"noun","ipa":"/ˈbɪldɪŋ/","gloss":"prédio"},{"surface":"downtown","pos":"adverb","ipa":"/ˌdaʊnˈtaʊn/","gloss":"para o centro"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-03-10', 'lesson-phrasal-b1-03', 10, 'phrasal', 'Please put your name down on the list.', 'Por favor, coloque seu nome na lista.', '/pliːz pʊt jʊr neɪm daʊn ɑːn ðə lɪst/', '"Put down" também é anotar, inscrever.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"list","pos":"noun","ipa":"/lɪst/","gloss":"lista"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-04-01', 'lesson-phrasal-b1-04', 1, 'phrasal', 'When are you coming back?', 'Quando você volta?', '/wɛn ɑːr juː ˈkʌmɪŋ bæk/', '"Come back" = voltar (para cá).', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"coming","pos":"verb","ipa":"/ˈkʌmɪŋ/","gloss":"vindo"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-02', 'lesson-phrasal-b1-04', 2, 'phrasal', 'She came up with a great idea.', 'Ela teve uma ótima ideia.', '/ʃiː keɪm ʌp wɪð ə ɡreɪt aɪˈdiːə/', '"Come up with" = inventar, ter (ideia, solução).', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"came","pos":"verb","ipa":"/keɪm/","gloss":"veio"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"great","pos":"adjective","ipa":"/ɡreɪt/","gloss":"ótimo"},{"surface":"idea","pos":"noun","ipa":"/aɪˈdiːə/","gloss":"ideia"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-03', 'lesson-phrasal-b1-04', 3, 'phrasal', 'The price came down last month.', 'O preço caiu no mês passado.', '/ðə praɪs keɪm daʊn læst mʌnθ/', '"Come down" = baixar, cair.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"price","pos":"noun","ipa":"/praɪs/","gloss":"preço"},{"surface":"came","pos":"verb","ipa":"/keɪm/","gloss":"veio"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-04', 'lesson-phrasal-b1-04', 4, 'phrasal', 'I came across an old photo.', 'Encontrei uma foto antiga por acaso.', '/aɪ keɪm əˈkrɔːs ən oʊld ˈfoʊtoʊ/', '"Come across" = encontrar por acaso.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"came","pos":"verb","ipa":"/keɪm/","gloss":"veio"},{"surface":"across","pos":"preposition","ipa":"/əˈkrɔːs/","gloss":"do outro lado de, atravessando"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"photo","pos":"noun","ipa":"/ˈfoʊtoʊ/","gloss":"foto"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-05', 'lesson-phrasal-b1-04', 5, 'phrasal', 'Come on, we are late!', 'Vamos, estamos atrasados!', '/kʌm ɑːn wiː ɑːr leɪt/', '"Come on" = vamos, anda logo. Informal.', '[]'::jsonb, '[{"surface":"Come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-06', 'lesson-phrasal-b1-04', 6, 'phrasal', 'Please go on, I am listening.', 'Por favor, continue, estou ouvindo.', '/pliːz ɡoʊ ɑːn aɪ æm ˈlɪsənɪŋ/', '"Go on" = continuar.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"listening","pos":"verb","ipa":"/ˈlɪsənɪŋ/","gloss":"ouvindo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-07', 'lesson-phrasal-b1-04', 7, 'phrasal', 'Let''s go out tonight.', 'Vamos sair hoje à noite.', '/lɛts ɡoʊ aʊt təˈnaɪt/', '"Go out" = sair (para se divertir).', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-08', 'lesson-phrasal-b1-04', 8, 'phrasal', 'Let''s go over the plan again.', 'Vamos revisar o plano de novo.', '/lɛts ɡoʊ ˈoʊvər ðə plæn əˈɡɛn/', '"Go over" = revisar.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-09', 'lesson-phrasal-b1-04', 9, 'phrasal', 'The alarm went off at three.', 'O alarme tocou às três.', '/ðə əˈlɑːrm wɛnt ɔːf æt θriː/', '"Go off" = disparar, tocar (alarme); também estragar (comida).', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"alarm","pos":"noun","ipa":"/əˈlɑːrm/","gloss":"despertador, alarme"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-04-10', 'lesson-phrasal-b1-04', 10, 'phrasal', 'Prices keep going up.', 'Os preços continuam subindo.', '/ˈpraɪsɪz kiːp ˈɡoʊɪŋ ʌp/', '"Go up/down" = subir/descer (valores).', '[]'::jsonb, '[{"surface":"Prices","pos":"noun","ipa":"/ˈpraɪsɪz/","gloss":"preços"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-05-01', 'lesson-phrasal-b1-05', 1, 'phrasal', 'I''m looking for my keys.', 'Estou procurando minhas chaves.', '/aɪm ˈlʊkɪŋ fɔːr maɪ kiːz/', '"Look for" = procurar. Não separável.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-02', 'lesson-phrasal-b1-05', 2, 'phrasal', 'Can you look after my dog?', 'Pode cuidar do meu cachorro?', '/kæn juː lʊk ˈæftər maɪ dɔːɡ/', '"Look after" = cuidar de. Não separável.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"dog","pos":"noun","ipa":"/dɔːɡ/","gloss":"cachorro"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-03', 'lesson-phrasal-b1-05', 3, 'phrasal', 'Look it up in the dictionary.', 'Procure no dicionário.', '/lʊk ɪt ʌp ɪn ðə ˈdɪkʃənɛri/', '"Look up" = procurar informação. Separável: "look it up".', '[]'::jsonb, '[{"surface":"Look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dictionary","pos":"noun","ipa":"/ˈdɪkʃənɛri/","gloss":"dicionário"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-04', 'lesson-phrasal-b1-05', 4, 'phrasal', 'I look forward to meeting you.', 'Estou ansioso para te conhecer.', '/aɪ lʊk ˈfɔːrwərd tuː ˈmiːtɪŋ juː/', '"Look forward to" + verbo com "-ing". Formal/neutro.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"forward","pos":"adverb","ipa":"/ˈfɔːrwərd/","gloss":"adiante (look forward)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-05', 'lesson-phrasal-b1-05', 5, 'phrasal', 'Look out! A car is coming.', 'Cuidado! Vem um carro.', '/lʊk aʊt ə kɑːr ɪz ˈkʌmɪŋ/', '"Look out" = cuidado! Informal.', '[]'::jsonb, '[{"surface":"Look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"coming","pos":"verb","ipa":"/ˈkʌmɪŋ/","gloss":"vindo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-06', 'lesson-phrasal-b1-05', 6, 'phrasal', 'Can you look into this problem?', 'Pode investigar este problema?', '/kæn juː lʊk ˈɪntuː ðɪs ˈprɑːbləm/', '"Look into" = investigar, analisar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-07', 'lesson-phrasal-b1-05', 7, 'phrasal', 'I look up to my father.', 'Admiro meu pai.', '/aɪ lʊk ʌp tuː maɪ ˈfɑːðər/', '"Look up to" = admirar alguém. Oposto: "look down on" = desprezar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"father","pos":"noun","ipa":"/ˈfɑːðər/","gloss":"pai"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-08', 'lesson-phrasal-b1-05', 8, 'phrasal', 'We looked around the old town.', 'Demos uma volta pela cidade antiga.', '/wiː lʊkt əˈraʊnd ðə oʊld taʊn/', '"Look around" = dar uma olhada ao redor.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"looked","pos":"verb","ipa":"/lʊkt/","gloss":"olhou, pareceu"},{"surface":"around","pos":"adverb","ipa":"/əˈraʊnd/","gloss":"ao redor, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"town","pos":"noun","ipa":"/taʊn/","gloss":"cidade pequena"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-09', 'lesson-phrasal-b1-05', 9, 'phrasal', 'Can you look over my email before I send it?', 'Pode revisar meu e-mail antes de eu mandar?', '/kæn juː lʊk ˈoʊvər maɪ ˈiːmeɪl bɪˈfɔːr aɪ sɛnd ɪt/', '"Look over" = revisar rapidamente.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"email","pos":"noun","ipa":"/ˈiːmeɪl/","gloss":"e-mail"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-05-10', 'lesson-phrasal-b1-05', 10, 'phrasal', 'Things are looking up.', 'As coisas estão melhorando.', '/θɪŋz ɑːr ˈlʊkɪŋ ʌp/', '"Look up" (sem objeto) = melhorar.', '[]'::jsonb, '[{"surface":"Things","pos":"noun","ipa":"/θɪŋz/","gloss":"coisas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-06-01', 'lesson-phrasal-b1-06', 1, 'phrasal', 'Turn off the lights when you leave.', 'Apague as luzes quando sair.', '/tɜːrn ɔːf ðə laɪts wɛn juː liːv/', '"Turn off/on" = desligar/ligar. Separável: "turn them off".', '[]'::jsonb, '[{"surface":"Turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"lights","pos":"noun","ipa":"/laɪts/","gloss":"luzes"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-02', 'lesson-phrasal-b1-06', 2, 'phrasal', 'Can you turn down the music?', 'Pode abaixar a música?', '/kæn juː tɜːrn daʊn ðə ˈmjuːzɪk/', '"Turn down/up" = abaixar/aumentar volume.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"music","pos":"noun","ipa":"/ˈmjuːzɪk/","gloss":"música"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-03', 'lesson-phrasal-b1-06', 3, 'phrasal', 'She turned down the job offer.', 'Ela recusou a oferta de emprego.', '/ʃiː tɜːrnd daʊn ðə dʒɑːb ˈɔːfər/', '"Turn down" também é recusar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"turned","pos":"verb","ipa":"/tɜːrnd/","gloss":"virou, ficou"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-04', 'lesson-phrasal-b1-06', 4, 'phrasal', 'He turned up late again.', 'Ele apareceu atrasado de novo.', '/hiː tɜːrnd ʌp leɪt əˈɡɛn/', '"Turn up" (sem objeto) = aparecer, chegar.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"turned","pos":"verb","ipa":"/tɜːrnd/","gloss":"virou, ficou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-05', 'lesson-phrasal-b1-06', 5, 'phrasal', 'It turned out to be true.', 'No fim, era verdade.', '/ɪt tɜːrnd aʊt tuː biː truː/', '"Turn out" = acabar sendo, revelar-se.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"turned","pos":"verb","ipa":"/tɜːrnd/","gloss":"virou, ficou"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-06', 'lesson-phrasal-b1-06', 6, 'phrasal', 'Don''t give up!', 'Não desista!', '/doʊnt ɡɪv ʌp/', '"Give up" = desistir.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-07', 'lesson-phrasal-b1-06', 7, 'phrasal', 'I gave up sugar last year.', 'Larguei o açúcar no ano passado.', '/aɪ ɡeɪv ʌp ˈʃʊɡər læst jɪr/', '"Give up" + coisa = largar um hábito.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"gave","pos":"verb","ipa":"/ɡeɪv/","gloss":"deu"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"sugar","pos":"noun","ipa":"/ˈʃʊɡər/","gloss":"açúcar"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-08', 'lesson-phrasal-b1-06', 8, 'phrasal', 'Give it back to me.', 'Me devolve isso.', '/ɡɪv ɪt bæk tuː miː/', '"Give back" = devolver. Separável.', '[]'::jsonb, '[{"surface":"Give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-09', 'lesson-phrasal-b1-06', 9, 'phrasal', 'The teacher gave out the exams.', 'O professor distribuiu as provas.', '/ðə ˈtiːtʃər ɡeɪv aʊt ðə ɪɡˈzæmz/', '"Give out" = distribuir.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"teacher","pos":"noun","ipa":"/ˈtiːtʃər/","gloss":"professor, professora"},{"surface":"gave","pos":"verb","ipa":"/ɡeɪv/","gloss":"deu"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"exams","pos":"noun","ipa":"/ɪɡˈzæmz/","gloss":"provas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-06-10', 'lesson-phrasal-b1-06', 10, 'phrasal', 'I finally gave in and bought it.', 'No fim eu cedi e comprei.', '/aɪ ˈfaɪnəli ɡeɪv ɪn ænd bɔːt ɪt/', '"Give in" = ceder, render-se.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"finally","pos":"adverb","ipa":"/ˈfaɪnəli/","gloss":"finalmente"},{"surface":"gave","pos":"verb","ipa":"/ɡeɪv/","gloss":"deu"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
